    82  /// <summary>
    83  /// Provided with a block pointer with populated type and length, this will actually parse out the body and options
    84  /// </summary>
    85  /// <param name="current">Block pointer with type and length filled out</param>
    86  /// <param name="local_data">Pointer to data which constitutes block body</param>
    87  /// <param name="block_start">Pointer to the start of the block data</param>
    88  void parse_by_block_type(struct _light_pcapng *current, const uint32_t *local_data, const uint32_t *block_start)
    89  {
    90     switch (current->block_type)
    91     {
    92        case LIGHT_SECTION_HEADER_BLOCK:
    93        {
    94           DPRINT_HERE(LIGHT_SECTION_HEADER_BLOCK);
    95           struct _light_section_header *shb = calloc(1, sizeof(struct _light_section_header));
    96           struct _light_option *opt = NULL;
    97           uint32_t version;
    98           int32_t local_offset;
    99
   100           shb->byteorder_magic = *local_data++;
   101           // TODO check byte order.
   102           version = *local_data++;
   103           shb->major_version = version & 0xFFFF;
   104           shb->minor_version = (version >> 16) & 0xFFFF;
   105           shb->section_length = *((uint64_t*)local_data);
   106           local_data += 2;
   107
   108           current->block_body = (uint32_t*)shb;
   109           local_offset = (size_t)local_data - (size_t)block_start;
   110           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
   111           current->options = opt;
   112        }
   113        break;
   114
   115        case LIGHT_INTERFACE_BLOCK:
   116        {
   117           DPRINT_HERE(LIGHT_INTERFACE_BLOCK);
   118           struct _light_interface_description_block *idb = calloc(1, sizeof(struct _light_interface_description_block));
   119           struct _light_option *opt = NULL;
   120           uint32_t link_reserved = *local_data++;

1           uint32_t link_reserved = *local_data++;
     2           int32_t local_offset;
     3
     4           idb->link_type = link_reserved & 0xFFFF;
     5           idb->reserved = (link_reserved >> 16) & 0xFFFF;
     6           idb->snapshot_length = *local_data++;
     7           current->block_body = (uint32_t*)idb;
     8           local_offset = (size_t)local_data - (size_t)block_start;
     9           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
    10           current->options = opt;
    11        }
    12        break;
    13
    14        case LIGHT_ENHANCED_PACKET_BLOCK:
    15        {
    16           DPRINT_HERE(LIGHT_ENHANCED_PACKET_BLOCK);
    17           struct _light_enhanced_packet_block *epb = NULL;
    18           struct _light_option *opt = NULL;
    19           uint32_t interface_id = *local_data++;
    20           uint32_t timestamp_high = *local_data++;
    21           uint32_t timestamp_low = *local_data++;
    22           uint32_t captured_packet_length = *local_data++;
    23           uint32_t original_packet_length = *local_data++;
    24           int32_t local_offset;
    25           uint32_t actual_len = 0;
    26
    27           PADD32(captured_packet_length, &actual_len);
    28
    29           epb = calloc(1, sizeof(struct _light_enhanced_packet_block) + actual_len);
    30           epb->interface_id = interface_id;
    31           epb->timestamp_high = timestamp_high;
    32           epb->timestamp_low = timestamp_low;
    33           epb->capture_packet_length = captured_packet_length;
    34           epb->original_capture_length = original_packet_length;
    35
    36           memcpy(epb->packet_data, local_data, captured_packet_length); // Maybe actual_len?
    37           local_data += actual_len / sizeof(uint32_t);
    38           current->block_body = (uint32_t*)epb;
    39           local_offset = (size_t)local_data - (size_t)block_start;
    40           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
    41           current->options = opt;
    42        }
    43        break;
    44
    45        case LIGHT_SIMPLE_PACKET_BLOCK:
    46        {
    47           DPRINT_HERE(LIGHT_SIMPLE_PACKET_BLOCK);
    48           struct _light_simple_packet_block *spb = NULL;
    49           uint32_t original_packet_length = *local_data++;
    50           uint32_t actual_len = current->block_total_length - 2 * sizeof(current->block_total_length) - sizeof(current->block_type) - sizeof(original_packet_length);
    51
    52           spb = calloc(1, sizeof(struct _light_enhanced_packet_block) + actual_len);
    53           spb->original_packet_length = original_packet_length;
    54
    55           memcpy(spb->packet_data, local_data, actual_len);
    56           local_data += actual_len / sizeof(uint32_t);
    57           current->block_body = (uint32_t*)spb;
    58           current->options = NULL; // No options defined by the standard for this block type.
    59        }
    60        break;
    61
    62        case LIGHT_CUSTOM_DATA_BLOCK:
    63        {
    64           DPRINT_HERE(LIGHT_CUSTOM_DATA_BLOCK);
    65           struct _light_custom_nonstandard_block *cnb = NULL;
    66           struct _light_option *opt = NULL;
    67           uint32_t len = *local_data++;
    68           uint32_t reserved0 = *local_data++;
    69           uint32_t reserved1 = *local_data++;
    70           int32_t local_offset;
    71           uint32_t actual_len = 0;
    72
    73           PADD32(len, &actual_len);
    74           cnb = calloc(1, sizeof(struct _light_custom_nonstandard_block) + actual_len);
    75           cnb->data_length = len;
    76           cnb->reserved0 = reserved0;
    77           cnb->reserved1 = reserved1;
    78
    79           memcpy(cnb->packet_data, local_data, len); // Maybe actual_len?
    80           local_data += actual_len / sizeof(uint32_t);
    81           current->block_body = (uint32_t*)cnb;
    82           local_offset = (size_t)local_data - (size_t)block_start;
    83           opt = __parse_options((uint32_t **)&local_data, current->block_total_length - local_offset - sizeof(current->block_total_length));
    84           current->options = opt;
    85        }
    86        break;
    87
    88        default: // Could not find registered block type. Copying data as RAW.
    89        {
    90           DPRINT_HERE(default);
    91           uint32_t raw_size = current->block_total_length - 2 * sizeof(current->block_total_length) - sizeof(current->block_type);
    92           if (raw_size > 0)
    93           {
    94              current->block_body = calloc(raw_size, 1);
    95              memcpy(current->block_body, local_data, raw_size);
    96              local_data += raw_size / (sizeof(*local_data));
    97           }
    98           else
    99           {
   100              current->block_body = NULL;
   101           }
